    src/pages/friend/[id].astro       ---      import   Layout   from     "  ../../layouts/Layout.astro  "  ;      import   { app }   from     "  ../../firebase/server  "  ;      import   { getFirestore }   from     "  firebase-admin/firestore  "  ;     
     interface   Friend {            name  :     string  ;            age  :     number  ;            isBestFriend  :     boolean  ;      }     
     const {   id   } =   Astro  .  params  ;     
     if   (  !  id) {          return   Astro  .  redirect  (  "  /404  "  );      }     
     const   db   =   getFirestore  (app);      const   friendsRef   =   db  .  collection  (  "  friends  "  );      const   friendSnapshot   = await   friendsRef  .  doc  (id)  .  get  ();     
     if   (  !  friendSnapshot  .  exists  ) {          return   Astro  .  redirect  (  "  /404  "  );      }     
     const   friend   =   friendSnapshot  .  data  ()   as   Friend  ;      ---     
     <  Layout     title  =  {  friend  .  name  }  >           <  h1  >   {  friend  .  name  }   </  h1  >            <  p  >   Age:   {  friend  .  age  }   </  p  >            <  p  >   Is best friend:   {  friend  .  isBestFriend     ?     "  Yes  "     :     "  No  "  }   </  p  >       </  Layout  >        <button title="Copy to clipboard" data-copied="Copied!" data-code="---import Layout from "../../layouts/Layout.astro";import { app } from "../../firebase/server";import { getFirestore } from "firebase-admin/firestore";interface Friend {  name: string;  age: number;  isBestFriend: boolean;}const { id } = Astro.params;if (!id) {  return Astro.redirect("/404");}const db = getFirestore(app);const friendsRef = db.collection("friends");const friendSnapshot = await friendsRef.doc(id).get();if (!friendSnapshot.exists) {  return Astro.redirect("/404");}const friend = friendSnapshot.data() as Friend;---    {friend.name}    Age: {friend.age}    Is best friend: {friend.isBestFriend ? "Yes" : "No"}  ">      
  Display a list of records with an edit button         Section titled “Display a list of records with an edit button”   
 Finally,  src/pages/dashboard.astro  will display a list of friends. Each friend will have a link to their details page and an edit button that will redirect the user to the edit page. 
    src/pages/dashboard.astro       ---      import   { app }   from     "  ../firebase/server  "  ;      import   { getFirestore }   from     "  firebase-admin/firestore  "  ;      import   Layout   from     "  ../layouts/Layout.astro  "  ;     
     interface   Friend {            id  :     string  ;            name  :     string  ;            age  :     number  ;            isBestFriend  :     boolean  ;      }     
     const   db   =   getFirestore  (app);      const   friendsRef   =   db  .  collection  (  "  friends  "  );      const   friendsSnapshot   = await   friendsRef  .  get  ();      const   friends   =   friendsSnapshot  .  docs  .  map  (  (  doc  )   =>   (  {            id:   doc  .  id  ,          ...  doc  .  data  ()  ,      }  ))   as   Friend  [];      ---     
